/**
 * Track-changes + comments DOCX round-trip (change track-changes-comments §8).
 *
 * - 8.5: load a DOCX with comments (threading + resolved + UTC dates) →
 *   save → reload → comments preserved (sidebar cards + commentRange markers).
 * - 8.6: load a DOCX with tracked changes (w:ins / w:del) → save → reload →
 *   revisions preserved (insertion/deletion marks + sidebar cards).
 *
 * Fixtures are generated by `bun run e2e/fixtures/generate-fixtures.ts`
 * (generateCommentsRoundtripDocx / generateTrackedChangesRoundtripDocx).
 */

import { test, expect, type Page } from '@playwright/test';
import { EditorPage } from '../helpers/editor-page';
import * as fs from 'fs';
import * as path from 'path';
import { fileURLToPath } from 'url';
import JSZip from 'jszip';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const COMMENTS_DOCX = path.join(__dirname, '..', 'fixtures', 'comments-roundtrip.docx');
const TRACKED_DOCX = path.join(__dirname, '..', 'fixtures', 'tracked-changes-roundtrip.docx');

const SIDEBAR = '.docx-unified-sidebar';
const COMMENT_CARD = '.docx-comment-card';
const TRACKED_CARD = '.docx-tracked-change-card';

async function saveDownload(page: Page): Promise<string> {
  const downloadPromise = page.waitForEvent('download');
  await page.locator('text=Save').click();
  const download = await downloadPromise;
  const downloadPath = await download.path();
  expect(downloadPath).toBeTruthy();
  return downloadPath!;
}

async function openSidebar(page: Page): Promise<void> {
  const toggle = page.locator('[aria-label="Toggle comments sidebar"]');
  if ((await toggle.getAttribute('aria-pressed')) !== 'true') {
    await toggle.click();
    await page.waitForTimeout(200);
  }
}

test.describe('Track-changes comments round-trip (§8)', () => {
  let editor: EditorPage;

  test.beforeEach(async ({ page }) => {
    editor = new EditorPage(page);
    await editor.goto();
    await editor.waitForReady();
  });

  test('8.5: comments survive save → reload (threading, resolved, markers)', async ({ page }) => {
    await editor.loadDocxFile(COMMENTS_DOCX);

    // Highlighted comment ranges are painted in the document body.
    await expect(page.locator('.paged-editor__pages [data-comment-id="0"]')).toBeVisible({
      timeout: 10000,
    });

    // Sidebar shows the top-level card + the resolved checkmark marker
    // (resolved comments render collapsed as a checkmark, not a full card).
    await openSidebar(page);
    await expect(page.locator(`${SIDEBAR} ${COMMENT_CARD}[data-comment-id="0"]`)).toBeVisible();
    await expect(
      page.locator(`${SIDEBAR} [data-comment-id="2"][data-comment-resolved="true"]`)
    ).toBeVisible();

    // Save and inspect the ZIP: comments.xml + range markers + threading parts.
    const downloadPath = await saveDownload(page);
    const zip = await JSZip.loadAsync(fs.readFileSync(downloadPath));

    const commentsXml = await zip.file('word/comments.xml')!.async('text');
    expect(commentsXml).toContain('Top-level review note');
    expect(commentsXml).toContain('Reply to Alice');
    expect(commentsXml).toContain('Already addressed');

    const docXml = await zip.file('word/document.xml')!.async('text');
    expect(docXml).toContain('<w:commentRangeStart w:id="0"');
    expect(docXml).toContain('<w:commentRangeEnd w:id="0"');

    const extendedXml = await zip.file('word/commentsExtended.xml')!.async('text');
    expect(extendedXml).toContain('w15:paraIdParent=');
    expect(extendedXml).toContain('w15:done="1"');

    // Reload the saved file — all three comments come back.
    const tempPath = path.join(__dirname, '..', 'fixtures', '_temp-comments-roundtrip.docx');
    fs.writeFileSync(tempPath, fs.readFileSync(downloadPath));
    try {
      await editor.loadDocxFile(tempPath);
      await expect(page.locator('.paged-editor__pages [data-comment-id="0"]')).toBeVisible({
        timeout: 10000,
      });
      await openSidebar(page);
      await expect(page.locator(`${SIDEBAR} ${COMMENT_CARD}[data-comment-id="0"]`)).toBeVisible();
      await expect(
        page.locator(`${SIDEBAR} [data-comment-id="2"][data-comment-resolved="true"]`)
      ).toBeVisible();
    } finally {
      if (fs.existsSync(tempPath)) fs.unlinkSync(tempPath);
    }
  });

  test('8.6: tracked changes survive save → reload (w:ins / w:del)', async ({ page }) => {
    await editor.loadDocxFile(TRACKED_DOCX);

    // Insertion + deletion marks are painted in the document body.
    await expect(page.locator('.paged-editor__pages .docx-insertion').first()).toBeVisible({
      timeout: 10000,
    });
    await expect(page.locator('.paged-editor__pages .docx-deletion').first()).toBeVisible();

    // Sidebar shows the two tracked-change cards.
    await openSidebar(page);
    await expect(page.locator(`${SIDEBAR} ${TRACKED_CARD}`)).toHaveCount(2);

    // Save and inspect the ZIP: w:ins / w:del with author + text.
    const downloadPath = await saveDownload(page);
    const zip = await JSZip.loadAsync(fs.readFileSync(downloadPath));
    const docXml = await zip.file('word/document.xml')!.async('text');
    expect(docXml).toContain('<w:ins');
    expect(docXml).toContain('<w:del');
    expect(docXml).toContain('inserted phrase');
    expect(docXml).toContain('deleted phrase');
    expect(docXml).toContain('w:author="Alice"');
    expect(docXml).toContain('w:author="Bob"');

    // Reload — insertion and deletion cards come back.
    const tempPath = path.join(__dirname, '..', 'fixtures', '_temp-tracked-roundtrip.docx');
    fs.writeFileSync(tempPath, fs.readFileSync(downloadPath));
    try {
      await editor.loadDocxFile(tempPath);
      await expect(page.locator('.paged-editor__pages .docx-insertion').first()).toBeVisible({
        timeout: 10000,
      });
      await expect(page.locator('.paged-editor__pages .docx-deletion').first()).toBeVisible();
      await openSidebar(page);
      await expect(page.locator(`${SIDEBAR} ${TRACKED_CARD}`)).toHaveCount(2);
    } finally {
      if (fs.existsSync(tempPath)) fs.unlinkSync(tempPath);
    }
  });
});
